styles:
.solution_item {
  display: flex;
}

.solution_item-icon{
  display: block;
  background: var(--c-white-bg);
  border-radius: 100px;
  text-align: center;
  width: 64px;
  height: 64px;
  flex-shrink: 0;
line-height: 77px;

}
.solution_item-icon img {
display: inline-block;
}

.solution_item-content {
  padding: 17px 0 0 20px;

}
.solution_item-title {
  font-size: 24px;
  line-height: 1.1em;
  margin-bottom: 24px;
  color: var(--c-white);
  font-weight: 500;
}
.solution_item-text {
  font-size: 14px;
  line-height: 1.6em;
  color: var(--c-white);
  font-weight: 300;
}
